solution_files.two-fer.wren:
// Two-fer with other names and layout.
class Greeter {
    static greet() { return "One for you, one for me." }

    /* with a name */
    static greet(person) {
        return "One for %(person), one for me."
    }
}

exercise_files.two-fer.spec.wren:
import "./two-fer" for Greeter
import "wren-testie/testie" for Testie, Expect
Testie.test("two-fer") {|do, skip|
  do.test("no name") { Expect.value(Greeter.greet()).toEqual("One for you, one for me.") }
}
Testie.run()
